    // The console's name as the "Add a game" window lists it, and the icon that stands for it.
    static readonly Dictionary<string, string> IconOfConsole = new()
    {
        ["Nintendo 64"] = "nintendo",
        ["GameCube"] = "nintendogamecube",
        ["Wii"] = "wii",
        ["Wii U"] = "wiiu",
        ["Super Nintendo"] = "nintendo",
        ["Nintendo (NES)"] = "nintendo",
        ["Game Boy"] = "nintendo",
        ["Game Boy Color"] = "nintendo",
        ["Game Boy Advance"] = "nintendo",
        ["Nintendo DS"] = "nintendods",
        ["Nintendo 3DS"] = "nintendo3ds",
        ["Nintendo Switch / other"] = "nintendoswitch",
        ["PlayStation"] = "playstation",
        ["PlayStation 2"] = "playstation2",
        ["PlayStation 3"] = "playstation3",
        ["PSP"] = "playstationportable",
        ["PS Vita"] = "playstationvita",
        ["Mega Drive / Genesis"] = "sega",
        ["Sega Saturn"] = "sega",
        ["Dreamcast"] = "sega",
        ["Xbox"] = "xbox",
        ["Xbox 360"] = "xbox",
    };

    /// <summary>The logo for a console of the "Add a game" list, or null (PC, or a console written by hand).</summary>
    public static Geometry? For(string? console) =>
        console is not null && IconOfConsole.TryGetValue(console, out var icon) ? Icons[icon] : null;

    static Geometry Frozen(string data)
    {
        var geometry = Geometry.Parse(data);
        geometry.Freeze();
        return geometry;
    }
}